async function getHealsHomeInfo() {
	if (!userInfo.value) return
	const body = await getHomeInfo();
	const tickets = Array.isArray(body) ? body : body?.data;
	const list = Array.isArray(tickets) ? tickets : [];
	// The home card shows one upcoming ticket, matching the RN home schedule.
	scheduleList.value = list.slice(0, 1);
}

