async function getDoctorList() {
	const payorId = Storage2.get('payorId');
	const params = {
		payorId: payorId || '',
		planId: pageState.planId || '',
		specialty: pageState.valueSpec || '',
		region: pageState.valueDist || 'Hong Kong',
		page: pageState.page || 1,
		limit: 10
	}
	pageState.loading = true;
	const {
		data
	} = await getProviderDoctors(params).finally(() => pageState.loading = false)
	doctorList.value = Array.isArray(data) ? data : [];
}
